import { useCallback, useEffect, useMemo, useRef, useState, type RefObject } from 'react'
import { Markdown } from '../document/Markdown.tsx'
import { fetchArtifactText, paths, type ReviewFinding, type RunDetail, type RunScope, type WorkerResult } from './api.ts'
import { fileAnchorId, NOT_CAPTURED_WORDING } from './files.ts'
import { linesNamed } from './findings.ts'
import { fileRows, filterRows, folderOf, type FileFilter, type FileRow } from './node/launch.ts'
import { ErrorPanel, LoadingPanel } from './panels.tsx'
import { keepInView } from './scroll.ts'
import { useResource, type Resource } from './useResource.ts'
import { useRunReview } from './useRunData.ts'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type Range = [number, number]

type Props = {
  scope: RunScope
  /** The node's latest result: the content a row opens on, and what a repair changed. */
  result: WorkerResult
  /** The worker's own freeze (`results/<lane>/1`) once loaded, which the rows list; null lists the latest result's. */
  frozen: WorkerResult | null
  /** The repair a changed file is credited to ("repair 1"); empty when no repair is recorded. */
  repairLabel: string
  /** The run's review node, whose recorded findings are shown on the files they name; null when the graph has none. */
  reviewNode: SnapshotNode | null
  refreshToken: number
  /** A captured file to open and scroll to, handed over by a review finding's file link; null otherwise. */
  focusPath: string | null
  onFocusApplied: () => void
}

/** From this many rows on, the list can be grouped by folder. */
const GROUP_MIN = 10

/** The review a finding list comes from, the same way the review node finds it; null when none is recorded. */
function reviewUriOf(scope: RunScope, node: SnapshotNode | null): string | null {
  if (node === null) return null
  if (node.result_uri !== null) return node.result_uri
  return node.status === 'pending' ? null : paths.review(scope, Math.max(node.attempt, 1))
}

function rangeText([from, to]: Range): string {
  return from === to ? `line ${from}` : `lines ${from}–${to}`
}

const plural = (count: number, word: string) => `${count} ${word}${count === 1 ? '' : 's'}`

/** The review findings that name this file, one line each: severity, reviewer, disposition, and the message cut to the row. */
function FileFindings({ findings, row, onShowLines }: { findings: Resource<ReviewFinding[] | null>; row: FileRow; onShowLines: (ranges: Range[]) => void }) {
  if (findings.status === 'idle' || (findings.status === 'ready' && findings.data === null)) {
    return <p className="projects-muted" data-testid="file-findings-no-review">No review is recorded for this run, so no findings are shown on its files.</p>
  }
  if (findings.status === 'loading') return <LoadingPanel>Loading the review findings…</LoadingPanel>
  if (findings.status === 'error') return <p className="projects-error-inline" role="alert">The recorded review could not be loaded, so findings on this file are not shown.</p>
  if (row.findings.length === 0) return <p className="projects-muted" data-testid="file-findings-none">No review finding names this file.</p>
  return (
    <ul className="file-findings" data-testid="file-findings">
      {row.findings.map((finding, index) => {
        const ranges = linesNamed(finding.message, row.path)
        return (
          <li key={index} className="file-finding" data-testid="file-finding" data-severity={finding.severity} data-reviewer={finding.reviewer} data-disposition={finding.disposition}>
            <span className="finding-severity">{finding.severity}</span>
            <span className="file-finding-who">· <span data-testid="file-finding-reviewer">{finding.reviewer}</span> · {finding.disposition} —</span>
            <span className="file-finding-message" title={finding.message}>{finding.message}</span>
            {ranges.length > 0 && (
              <button type="button" className="button button-small" data-testid="show-lines" onClick={() => onShowLines(ranges)}>
                Show {ranges.map(rangeText).join(', ')}
              </button>
            )}
          </li>
        )
      })}
    </ul>
  )
}

/** The exact file content, one element per line; lines a finding names are marked. */
function FileSource({ text, marked, preRef }: { text: string; marked: Range[]; preRef: RefObject<HTMLPreElement | null> }) {
  const lines = text.endsWith('\n') ? text.slice(0, -1).split('\n') : text.split('\n')
  const isMarked = (line: number) => marked.some(([from, to]) => line >= from && line <= to)
  return (
    <pre className="artifact-log file-content" data-testid="file-source" tabIndex={0} ref={preRef}>
      {lines.map((line, index) => {
        const number = index + 1
        return isMarked(number)
          ? <mark key={number} data-line={number} data-finding-line="true">{line}{'\n'}</mark>
          : <span key={number} data-line={number}>{line}{'\n'}</span>
      })}
    </pre>
  )
}

/** What a row says after its path: how a repair touched the file, and where its first finding points. */
function RowMarks({ row }: { row: FileRow }) {
  // The most severe finding names the row's severity; its reviewer and lines follow the path.
  const first = row.findings.find(entry => entry.severity === row.severity)
  const lines = first ? linesNamed(first.message, row.path) : []
  const hint = first ? [first.reviewer, ...(lines.length > 0 ? [rangeText(lines[0])] : []), ...(row.findings.length > 1 ? [`+${row.findings.length - 1} more`] : [])].join(' · ') : null
  return (
    <span className="file-row-meta">
      {row.repair && (
        <span className="file-repair" title={`${row.repair.kind === 'added' ? 'Added' : 'Changed'} by the operator's ${row.repair.label} after the worker's freeze`}>
          ⚒ {row.repair.label} · {row.repair.kind}
        </span>
      )}
      {hint && <span>{hint}</span>}
      {row.markdown && <span>Markdown</span>}
    </span>
  )
}

/**
 * One captured file as a dense row (docs/PRD_VIEWER_UX.md 4.5, 7): a `<details>` whose summary is its path. Nothing is
 * fetched until the row opens. An opened row shows the sha256, the findings on the file as one-line chips, then the content:
 * Markdown on Rendered with a Source view, anything else as source. "Show lines" switches to the source and marks them.
 */
function CapturedFileRow({ scope, row, findings, focused }: { scope: RunScope; row: FileRow; findings: Resource<ReviewFinding[] | null>; focused: boolean }) {
  const file = row.file!
  const [open, setOpen] = useState(focused)
  const [view, setView] = useState<'rendered' | 'source'>(row.markdown ? 'rendered' : 'source')
  const [marked, setMarked] = useState<Range[]>([])
  const [scrollRequest, setScrollRequest] = useState(0)
  const preRef = useRef<HTMLPreElement>(null)
  const rowRef = useRef<HTMLDetailsElement>(null)
  const load = useCallback((signal: AbortSignal) => fetchArtifactText(scope, file.artifact_id, signal), [scope, file.artifact_id])
  const { state, reload } = useResource(open ? `file:${file.artifact_id}` : null, load)

  useEffect(() => {
    const element = rowRef.current
    if (!focused || !element) return
    element.querySelector('summary')?.focus({ preventScroll: true })
    return keepInView(element, { block: 'start' })
  }, [focused])
  useEffect(() => {
    if (scrollRequest === 0 || state.status !== 'ready') return
    preRef.current?.querySelector('[data-finding-line]')?.scrollIntoView({ block: 'center' })
  }, [scrollRequest, state.status])

  const showLines = (ranges: Range[]) => {
    setMarked(ranges)
    setView('source')
    setScrollRequest(previous => previous + 1)
  }
  return (
    <details
      ref={rowRef}
      id={fileAnchorId(row.path)}
      className="file-row"
      data-testid="captured-file"
      data-path={row.path}
      data-view={open ? view : 'closed'}
      open={open}
      onToggle={event => setOpen(event.currentTarget.open)}
    >
      <summary className="file-row-summary">
        <span className="file-row-severity">{row.severity}</span>
        <code className="file-row-path" title={row.path}>{row.path}</code>
        <RowMarks row={row} />
      </summary>
      {open && (
        <div className="file-row-body">
          <div className="file-row-facts">
            <span className="projects-muted">sha256 <code title={file.sha256}>{file.sha256.slice(0, 12)}…</code>{row.repair && ` · as after ${row.repair.label}`}</span>
            {row.markdown && (
              <span role="group" aria-label={`View of ${row.path}`} className="task-toggle">
                <button type="button" className="button button-small" aria-pressed={view === 'rendered'} onClick={() => setView('rendered')}>Rendered</button>
                <button type="button" className="button button-small" aria-pressed={view === 'source'} onClick={() => setView('source')}>Source</button>
              </span>
            )}
          </div>
          <FileFindings findings={findings} row={row} onShowLines={showLines} />
          {state.status === 'loading' && <LoadingPanel>Loading {row.path}…</LoadingPanel>}
          {state.status === 'error' && <ErrorPanel error={state.error} what={`The captured file ${row.path}`} onRetry={reload} />}
          {state.status === 'ready' && (
            state.data.length === 0
              ? <p className="projects-muted">This file is empty.</p>
              : view === 'rendered'
                ? <div className="task-rendered file-content" data-testid="file-rendered"><Markdown content={state.data} inert /></div>
                : <FileSource text={state.data} marked={marked} preRef={preRef} />
          )}
        </div>
      )}
    </details>
  )
}

function FileRowItem({ scope, row, findings, focused }: { scope: RunScope; row: FileRow; findings: Resource<ReviewFinding[] | null>; focused: boolean }) {
  return (
    <li data-testid="created-file" data-path={row.path} data-state={row.state} data-reason={row.reason ?? undefined} data-repair={row.repair?.kind} data-findings={row.findings.length}>
      {row.file ? (
        <CapturedFileRow scope={scope} row={row} findings={findings} focused={focused} />
      ) : (
        <div className="file-row-summary file-row-static">
          <span className="file-row-severity">{row.severity}</span>
          <code className="file-row-path" title={row.path}>{row.path}</code>
          <span className="file-row-meta">
            {row.reason && <span data-testid="not-captured-reason">{NOT_CAPTURED_WORDING[row.reason]}</span>}
            {row.state === 'unlisted' && <span>not captured, and no reason was recorded</span>}
          </span>
        </div>
      )}
    </li>
  )
}

/**
 * "Files created or changed" on a launch node (docs/PRD_VIEWER_UX.md 4.5, 7): one dense row per file the worker froze at
 * handoff (`results/<lane>/1`), plus any file a repair added, with the review's findings first. Filters narrow the list to
 * the files with findings or those the repair touched, and a long list can be grouped by folder. A result recorded before
 * capture lists the paths and says the files were not captured.
 */
export function CreatedFiles({ scope, result, frozen, repairLabel, reviewNode, refreshToken, focusPath, onFocusApplied }: Props) {
  const listed = frozen ?? result
  const recorded = listed.files_not_captured !== undefined || listed.artifacts.some(artifact => artifact.kind === 'file')
  const repair = repairLabel || 'a repair'
  // Read through the run's cache; a review that was not there yet is asked again once the review node moves on, or on Refresh.
  const review = useRunReview(scope, recorded ? reviewUriOf(scope, reviewNode) : null, `${refreshToken}:${reviewNode?.status}:${reviewNode?.attempt}`)
  const findings: Resource<ReviewFinding[] | null> = review.status === 'ready' ? { status: 'ready', data: review.data?.findings ?? null } : review
  const findingList = findings.status === 'ready' ? findings.data : null
  const rows = useMemo(() => fileRows(frozen, result, findingList, repair), [frozen, result, findingList, repair])
  const withFindings = rows.filter(row => row.findings.length > 0).length
  const repaired = rows.filter(row => row.repair !== null).length
  const [filter, setFilter] = useState<FileFilter>('all')
  const [grouped, setGrouped] = useState(false)
  const shown = filterRows(rows, filter)

  // A file link is applied once: the target row opens and scrolls into view when it mounts, and the run view forgets it.
  const [focus] = useState(() => focusPath)
  useEffect(() => {
    if (focus !== null) onFocusApplied()
  }, [focus, onFocusApplied])

  const filters: { key: FileFilter; label: string; count: number }[] = [
    ...(withFindings > 0 ? [{ key: 'findings' as const, label: 'With findings', count: withFindings }] : []),
    ...(repaired > 0 ? [{ key: 'repair' as const, label: `${repair.charAt(0).toUpperCase()}${repair.slice(1)} ·`, count: repaired }] : []),
  ]
  const item = (row: FileRow) => <FileRowItem key={row.path} scope={scope} row={row} findings={findings} focused={focus === row.path} />
  return (
    <section className="evidence-section launch-files" aria-labelledby="evidence-created-files" data-testid="created-files" data-captured={rows.filter(row => row.file).length}>
      <div className="launch-files-head">
        <h4 id="evidence-created-files">Files created or changed</h4>
        <span className="projects-muted" data-testid="files-summary">
          {plural(rows.length, 'file')} {frozen ? 'frozen at handoff' : 'in the result'}
          {withFindings > 0 && ` · ${withFindings} with findings`}
          {repaired > 0 && ` · ${repaired} by ${repair}`}
        </span>
      </div>
      {rows.length === 0 ? (
        <p className="projects-muted" data-testid="changed-files-empty">No changed files were recorded.</p>
      ) : (
        <>
          {!recorded && (
            <p className="projects-muted" data-testid="files-not-captured">
              Created files were not captured for this run (its results predate file capture), so only their paths are listed.
            </p>
          )}
          {(filters.length > 0 || rows.length >= GROUP_MIN) && (
            <div className="launch-files-tools">
              {filters.length > 0 && (
                <div role="group" aria-label="Show files" className="task-toggle" data-testid="file-filters">
                  {[...filters, { key: 'all' as const, label: 'All', count: rows.length }].map(entry => (
                    <button key={entry.key} type="button" className="button button-small" aria-pressed={filter === entry.key} onClick={() => setFilter(entry.key)}>
                      {entry.label} {entry.count}
                    </button>
                  ))}
                </div>
              )}
              {rows.length >= GROUP_MIN && (
                <label className="launch-files-group">
                  <input type="checkbox" checked={grouped} onChange={event => setGrouped(event.currentTarget.checked)} /> Group by folder
                </label>
              )}
            </div>
          )}
          <ul className="file-rows" data-testid="changed-files">
            {grouped
              ? [...new Set(shown.map(row => folderOf(row.path)))].sort().map(folder => {
                const inFolder = shown.filter(row => folderOf(row.path) === folder)
                return (
                  <li key={folder} className="file-group" data-folder={folder}>
                    <span className="file-group-name">{folder === '' ? 'Repository root' : folder} <span className="projects-muted">{inFolder.length}</span></span>
                    <ul className="file-rows">{inFolder.map(item)}</ul>
                  </li>
                )
              })
              : shown.map(item)}
          </ul>
          {focus !== null && !rows.some(row => row.path === focus && row.file) && (
            <p className="projects-muted" data-testid="file-focus-missing">The linked file <code>{focus}</code> is not among this node's captured files.</p>
          )}
        </>
      )}
    </section>
  )
}
/**
 * The run-scoped cache of immutable evidence (docs/PRD_VIEWER_UX.md 7): worker and candidate results (`results/<lane>/<k>`)
 * and recorded reviews (`reviews/<n>`) never change once served, so each URI is read once and kept for as long as the page
 * lives, shared by the run page's Now banner, the node pages and their attempt strips. Only the run detail, its events and
 * its inputs poll. A URI that answered 404 or failed is asked again when the caller's `stamp` changes: a Refresh, or new
 * events, after which a result that did not exist yet may.
 */
import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from 'react'
import {
  fetchReviewResult, fetchWorkerResult, NOT_RECORDED, orNotRecorded, ProjectsApiError, scopedResultPath, scopedReviewPath,
  type ReviewResult, type RunScope, type WorkerResult,
} from './api.ts'
import type { Resource } from './useResource.ts'

type Entry =
  | { status: 'ready'; value: unknown }
  /** A 404: not there (yet); asked again under another stamp. */
  | { status: 'absent'; error: unknown; stamp: string }
  | { status: 'failed'; error: unknown; stamp: string }

/** Enough for every attempt of a long run's steps; the oldest entries go first. */
const CACHE_LIMIT = 400
const cache = new Map<string, Entry>()
const inflight = new Set<string>()
const listeners = new Set<() => void>()
let version = 0

function settle(key: string, entry: Entry) {
  cache.delete(key)
  cache.set(key, entry)
  if (cache.size > CACHE_LIMIT) cache.delete(cache.keys().next().value!)
  version += 1
  listeners.forEach(listener => listener())
}

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => { listeners.delete(listener) }
}

type Fetcher = (uri: string) => Promise<unknown>

/** Fetches every URI the cache does not hold under this stamp; re-renders whenever any entry settles. */
function useCached(kind: 'result' | 'review', uris: readonly string[], stamp: string, fetcher: Fetcher): (uri: string) => Entry | undefined {
  const current = useSyncExternalStore(subscribe, () => version, () => version)
  const key = uris.join('\n')
  useEffect(() => {
    for (const uri of key === '' ? [] : key.split('\n')) {
      const cacheKey = `${kind}:${uri}`
      const known = cache.get(cacheKey)
      if (inflight.has(cacheKey) || (known && (known.status === 'ready' || known.stamp === stamp))) continue
      inflight.add(cacheKey)
      fetcher(uri).then(
        value => settle(cacheKey, { status: 'ready', value }),
        (error: unknown) => settle(cacheKey, error instanceof ProjectsApiError && error.notFound ? { status: 'absent', error, stamp } : { status: 'failed', error, stamp }),
      ).finally(() => inflight.delete(cacheKey))
    }
    // The fetcher is rebuilt per render; the scope it closes over is part of every URI.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind, key, stamp])
  // `current` re-reads the cache whenever an entry settles.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useCallback((uri: string) => cache.get(`${kind}:${uri}`), [kind, current])
}

/** A result URI outside this run's results route is never fetched; it reads as absent. */
function resultFetcher(scope: RunScope): Fetcher {
  return uri => {
    const path = scopedResultPath(scope, uri)
    if (path === null) return Promise.reject(new ProjectsApiError('http', `The result link ${uri} is outside this run's results route.`, uri, { status: 404 }))
    return fetchWorkerResult(scope, path)
  }
}

/**
 * Several results at once: those that loaded, and how many were never answered yet. A result that answered 404 counts as
 * absent, not as loading; another failure counts as settled and is asked again under the next stamp.
 */
export function useRunResults(scope: RunScope, uris: readonly string[], stamp: string): { results: ReadonlyMap<string, WorkerResult>; pending: number } {
  const read = useCached('result', uris, stamp, resultFetcher(scope))
  const key = uris.join('\n')
  return useMemo(() => {
    const results = new Map<string, WorkerResult>()
    let pending = 0
    for (const uri of key === '' ? [] : key.split('\n')) {
      const entry = read(uri)
      if (entry?.status === 'ready') results.set(uri, entry.value as WorkerResult)
      else if (!entry) pending += 1
    }
    return { results, pending }
  }, [key, read])
}

/** A settled failure stays shown while a later stamp asks again, like a failed background reload. */
function asResource<T>(entry: Entry | undefined): Resource<T> {
  if (entry?.status === 'ready') return { status: 'ready', data: entry.value as T }
  if (entry) return { status: 'error', error: entry.error }
  return { status: 'loading' }
}

/** One result, as a resource: a node's own result, where a 404 is an error to show rather than an absence. `reload` asks again. */
export function useRunResult(scope: RunScope, uri: string | null, stamp: string): { state: Resource<WorkerResult>; reload: () => void } {
  const [retry, setRetry] = useState(0)
  const full = `${stamp}:${retry}`
  const read = useCached('result', uri === null ? [] : [uri], full, resultFetcher(scope))
  const reload = useCallback(() => setRetry(previous => previous + 1), [])
  return { state: uri === null ? { status: 'idle' } : asResource<WorkerResult>(read(uri)), reload }
}

/** The recorded review, read once per URI; a run whose export predates reviews has none (null). */
export function useRunReview(scope: RunScope, uri: string | null, stamp: string): Resource<ReviewResult | null> {
  const fetcher: Fetcher = reviewUri => {
    const path = scopedReviewPath(scope, reviewUri)
    if (path === null) return Promise.reject(new ProjectsApiError('http', `The review link ${reviewUri} is outside this run's reviews route.`, reviewUri, { status: 404 }))
    return orNotRecorded(fetchReviewResult(scope, path), NOT_RECORDED.review)
  }
  const read = useCached('review', uri === null ? [] : [uri], stamp, fetcher)
  return uri === null ? { status: 'idle' } : asResource<ReviewResult | null>(read(uri))
}
  if (!/^[1-9][0-9]*$/.test(resultUri.slice(prefix.length))) return null
  return resultUri
}

export function fetchReviewResult(scope: RunScope, reviewPath: string, signal?: AbortSignal): Promise<ReviewResult> {
  return requestJson(reviewPath, input => {
    const review = validateReviewResult(input)
    if (review.run_id !== scope.runId) throw new Error(`the review belongs to run ${review.run_id}.`)
    return review
  }, signal)
}

export function fetchRunInputs(scope: RunScope, signal?: AbortSignal): Promise<RunInputs> {
  return requestJson(paths.inputs(scope), input => {
    const inputs = validateRunInputs(input)
    if (inputs.run_id !== scope.runId) throw new Error(`the inputs belong to run ${inputs.run_id}.`)
    return inputs
  }, signal)
}

/** Whether a failure is the contract's 404 for a section the run's export does not carry. */
export function isNotRecorded(error: unknown, code: string): boolean {
  return error instanceof ProjectsApiError && error.notFound && error.code === code
}

/** Resolves to null when the section is not recorded (the contract's 404 code); every other failure propagates. */
export async function orNotRecorded<T>(request: Promise<T>, code: string): Promise<T | null> {
  try {
    return await request
  } catch (error) {
    if (isNotRecorded(error, code)) return null
    throw error
  }
}

 * line, then the Run and Assignment tabs; the Run view holds the fitted graph, the Steps table and Activity. A node page:
 * the one-line run bar, the tabs, the sticky step strip and the node in full width. One clock ticks here while the run can
 * still change; selecting a step moves the focus to its heading, and coming back returns it to the step's row.
 */
export function RunView({ scope, detail, current, selectedNodeId, selectedAttempt = null, tab, refreshToken, pollToken = 0, freshness, onNavigate, onAnnounce }: Props) {
  const { summary, definition, snapshot } = detail
  const clock = useNow(summary.status !== 'succeeded' && summary.status !== 'cancelled')
  const [zone] = useTimeZone()
  const runStart = useTimeReference()
  const snapshotById = new Map(snapshot.nodes.map(node => [node.node_id, node]))
  const selectedDefinition = selectedNodeId === null ? null : definition.nodes.find(node => node.node_id === selectedNodeId) ?? null
  const selectedState = selectedNodeId === null ? null : snapshotById.get(selectedNodeId) ?? null

  const runKey = `${scope.projectId}/${scope.workflowId}/${scope.runId}`
  const loadEvents = useCallback((signal: AbortSignal) => fetchEvents(scope, signal), [scope])
  const { state: events, reload: reloadEvents } = useResource(`events:${runKey}`, loadEvents, refreshToken, pollToken)
  // The inputs are one resource per run; a 404 INPUTS_NOT_FOUND means "not recorded", which loads as null.
  const loadInputs = useCallback((signal: AbortSignal) => orNotRecorded(fetchRunInputs(scope, signal), NOT_RECORDED.inputs), [scope])
  const { state: inputs, reload: reloadInputs } = useResource(`inputs:${runKey}`, loadInputs, refreshToken, pollToken)
  // The recorded review and the lane results are immutable per URI: read once through the run's cache (docs/PRD_VIEWER_UX.md 7).
  const reviewPath = snapshot.nodes.find(node => node.node_id === 'review')?.result_uri ?? null
  const review = useRunReview(scope, reviewPath, String(refreshToken))

  const eventsData = events.status === 'ready' ? events.data : null
  const inputsData = inputs.status === 'ready' ? inputs.data : null
  const reviewData = review.status === 'ready' ? review.data : null
  const uris = useMemo(() => (eventsData === null ? [] : nowResultUris(detail, eventsData)), [detail, eventsData])
  const { results, pending } = useRunResults(scope, uris, String(refreshToken))
  const run: RunData | null = useMemo(
    () => (eventsData === null ? null : { detail, events: eventsData, inputs: inputsData, review: reviewData, results }),
    [detail, eventsData, inputsData, reviewData, results],
  )
